/**
 * The site's languages. English pages live at the root of src/pages; each other locale mirrors them
 * under src/pages/<code>/, generated by scripts/translate.ts.
 */
export const locales = ['en', 'zh-cn', 'zh-tw'] as const;
export type Locale = (typeof locales)[number];

export const localeInfo: Record<Locale, { lang: string; og: string; name: string; short: string }> = {
  en: { lang: 'en', og: 'en_US', name: 'English', short: 'EN' },
  'zh-cn': { lang: 'zh-CN', og: 'zh_CN', name: '简体中文', short: '简' },
  'zh-tw': { lang: 'zh-TW', og: 'zh_TW', name: '繁體中文', short: '繁' },
};

const prefixed = locales.filter((l) => l !== 'en');

function segments(pathname: string): string[] {
  return pathname
    .replace(/\.html$/, '')
    .split('/')
    .filter((s) => s && s !== 'index');
}

/** The locale a path belongs to: its first segment if that's a locale, otherwise English. */
export function localeOf(pathname: string): Locale {
  const first = segments(pathname)[0];
  return (prefixed as readonly string[]).includes(first) ? (first as Locale) : 'en';
}

/** The path without its locale, `.html` or trailing slash: `/zh-cn/docs/hosting.html` is `/docs/hosting`. */
export function routeOf(pathname: string): string {
  const parts = segments(pathname);
  if (localeOf(pathname) !== 'en') parts.shift();
  return '/' + parts.join('/');
}

/** The path of `route` in `locale`. The home page has no trailing slash, as it's built to `zh-cn.html`. */
export function localize(route: string, locale: Locale): string {
  if (locale === 'en') return route;
  return route === '/' ? `/${locale}` : `/${locale}${route}`;
}

/**
 * Points the site links in a piece of HTML at `locale`'s pages, so docs and strings can link to
 * `/docs/hosting` in every language. Files, such as `/favicon.svg`, are left alone.
 */
export function localizeLinks(html: string, locale: Locale): string {
  if (locale === 'en') return html;
  return html.replace(/href="(\/(?!\/)[^"#?.]*)([#?][^"]*)?"/g,
    (_, route: string, rest = '') => `href="${localize(route, locale)}${rest}"`);
}

/** `getStaticPaths` entries for a page in every language: no prefix for English. */
export function localePaths() {
  return locales.map((locale) => ({ params: { lang: locale === 'en' ? undefined : locale } }));
}
